package com.hotupdaterexample.brownfield

import android.app.Activity
import android.app.Application
import android.content.Context
import android.view.View
import com.facebook.react.PackageList
import com.facebook.react.ReactHost
import com.facebook.react.bridge.JSBundleLoader
import com.facebook.react.common.annotations.UnstableReactNativeAPI
import com.facebook.react.defaults.DefaultComponentsRegistry
import com.facebook.react.defaults.DefaultReactHostDelegate
import com.facebook.react.defaults.DefaultTurboModuleManagerDelegate
import com.facebook.react.fabric.ComponentFactory
import com.facebook.react.interfaces.fabric.ReactSurface
import com.facebook.react.runtime.ReactHostImpl
import com.facebook.react.runtime.hermes.HermesInstance
import com.hotupdater.HotUpdater
import com.hotupdater.HotUpdaterInstance
import com.hotupdater.HotUpdaterOptions
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch

/**
 * The E2E host's second Hot Updater instance, `widget`: a React Native runtime
 * of its own beside the example's, with its own embedded bundle
 * (`widget.android.bundle`, from `index.widget.js`) on its own channel. Its
 * bundles, crash history, and recovery stay apart from the example's.
 *
 * Like the example's start, it checks for its update natively before its
 * runtime starts and reports the status as `widgetNativeCheckResult`; its
 * JavaScript only calls `HotUpdater.init`. React Native Brownfield runs one
 * React host, and `getDefaultReactHost` keeps one per process, so this one
 * builds its host itself. A scenario turns it on; every other scenario runs
 * the example alone.
 */
object HotUpdaterWidgetHost {
    private const val MODULE_NAME = "HotUpdaterWidget"
    private const val BUNDLE_ASSET_NAME = "widget.android.bundle"

    // Outlives every activity, so closing a screen never cancels the check.
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
    private var reactHost: ReactHost? = null
    private var surface: ReactSurface? = null

    /** Whether a scenario turned the widget on, so the host leaves room for it. */
    fun isEnabled(context: Context): Boolean = readRequest(context) != null

    /**
     * Hands [onView] the widget's React Native root for [activity] on the main
     * thread, or null when it is off. Call it once the example's bundle has
     * loaded, as the iOS host does.
     */
    fun createView(
        activity: Activity,
        onView: (View?) -> Unit,
    ) {
        surface?.let { return onView(it.view) }
        val request = readRequest(activity) ?: return onView(null)
        val application = activity.application
        scope.launch {
            val host =
                reactHost ?: run {
                    val widget = createInstance(application, request) ?: return@launch onView(null)
                    request.report(ReactNativeHostManager.checkForUpdate(widget, request), field = "widgetNativeCheckResult")
                    // Another call may have created it while this one checked.
                    reactHost ?: createReactHost(application, widget).also { reactHost = it }
                }
            if (activity.isFinishing || activity.isDestroyed) return@launch onView(null)
            surface?.let { return@launch onView(it.view) }
            host.onHostResume(activity)
            val created = host.createSurface(activity, MODULE_NAME, null)
            created.start()
            surface = created
            onView(created.view)
        }
    }

    fun onResume(activity: Activity) {
        if (surface != null) reactHost?.onHostResume(activity)
    }

    fun onPause(activity: Activity) {
        if (surface != null) reactHost?.onHostPause(activity)
    }

    /** The surface belongs to [activity]; the host lives on for the next one. */
    fun onDestroy(activity: Activity) {
        val current = surface ?: return
        current.stop()
        current.detach()
        surface = null
        reactHost?.onHostDestroy(activity)
    }

    private fun readRequest(context: Context) = NativeUpdateCheckRequest.read(context, NativeUpdateCheckRequest.WIDGET_KEY)

    /**
     * Its own name keeps its state apart; channel and embedded bundle are the
     * widget's, while the fingerprint and signing key are the app's.
     */
    private fun createInstance(
        application: Application,
        request: NativeUpdateCheckRequest,
    ): HotUpdaterInstance? =
        runCatching {
            HotUpdater.init(
                application,
                HotUpdaterOptions(
                    baseURL = request.baseURL,
                    requestTimeoutMillis = request.requestTimeoutMillis,
                    name = "widget",
                    channel = "widget",
                    bundleAssetName = BUNDLE_ASSET_NAME,
                ),
            )
        }.getOrNull()

    /** Starts with the bundle the widget's instance picks, after its check. */
    @OptIn(UnstableReactNativeAPI::class)
    private fun createReactHost(
        application: Application,
        widget: HotUpdaterInstance,
    ): ReactHost {
        val bundleFile = widget.getJSBundleFile()
        val bundleLoader =
            if (bundleFile.startsWith("assets://")) {
                JSBundleLoader.createAssetLoader(application, bundleFile, true)
            } else {
                JSBundleLoader.createFileLoader(bundleFile)
            }
        val delegate =
            DefaultReactHostDelegate(
                jsMainModulePath = "index.widget",
                jsBundleLoader = bundleLoader,
                reactPackages = PackageList(application).packages,
                jsRuntimeFactory = HermesInstance(),
                turboModuleManagerDelegateBuilder = DefaultTurboModuleManagerDelegate.Builder(),
            )
        val componentFactory = ComponentFactory()
        DefaultComponentsRegistry.register(componentFactory)
        return ReactHostImpl(application, delegate, componentFactory, false, false)
    }
}

package com.hotupdaterexample.brownfield

import android.app.Application
import android.content.Context
import com.callstack.reactnativebrownfield.OnJSBundleLoaded
import com.callstack.reactnativebrownfield.ReactNativeBrownfield
import com.facebook.react.PackageList
import com.facebook.react.defaults.DefaultReactHost.getDefaultReactHost
import com.hotupdater.HotUpdater
import com.hotupdater.HotUpdaterCheckOptions
import com.hotupdater.HotUpdaterInstance
import com.hotupdater.HotUpdaterOptions
import com.hotupdater.HotUpdaterUpdateStrategy
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL

/**
 * Starts React Native for the brownfield E2E host, as the brownfield guide
 * does: when a scenario turns it on, a `HotUpdaterInstance` checks for an
 * update first.
 */
object ReactNativeHostManager {
    // Outlives every activity, so closing a screen never cancels the start.
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Main)
    private val onStarted = mutableListOf<() -> Unit>()
    private var started = false
    private val onBundleLoaded = mutableListOf<() -> Unit>()
    private var bundleLoaded = false

    fun start(application: Application) {
        scope.launch {
            NativeUpdateCheckRequest.read(application, NativeUpdateCheckRequest.MAIN_KEY)?.let { request ->
                val status =
                    runCatching {
                        HotUpdater.init(
                            application,
                            HotUpdaterOptions(baseURL = request.baseURL, requestTimeoutMillis = request.requestTimeoutMillis),
                        )
                    }.fold(onSuccess = { checkForUpdate(it, request) }, onFailure = { "failed" })
                request.report(status, field = "nativeCheckResult")
            }
            val loaded =
                OnJSBundleLoaded {
                    scope.launch {
                        bundleLoaded = true
                        onBundleLoaded.toList().forEach { it() }
                        onBundleLoaded.clear()
                    }
                }
            ReactNativeBrownfield.initialize(application, loaded) {
                getDefaultReactHost(
                    context = application,
                    packageList = PackageList(application).packages,
                    jsMainModulePath = "index",
                    jsBundleAssetPath = "index.android.bundle",
                    jsBundleFilePath = HotUpdater.getJSBundleFile(application),
                    useDevSupport = false,
                    jsRuntimeFactory = null,
                )
            }
            HotUpdater.setReactHost(ReactNativeBrownfield.shared.reactHost)
            started = true
            onStarted.toList().forEach { it() }
            onStarted.clear()
        }
    }

    /**
     * The brownfield guide's update check for [hotUpdater], run before the
     * React Native runtime that uses it starts: checks, and waits up to the
     * request's timeout for a required update, which then runs in this start.
     * Any other update downloads in the background and runs at the next start.
     * The timeout ends the wait, not the download.
     */
    internal suspend fun checkForUpdate(
        hotUpdater: HotUpdaterInstance,
        request: NativeUpdateCheckRequest,
    ): String =
        withTimeoutOrNull(request.checkTimeoutMillis) {
            try {
                val strategy =
                    if (request.updateStrategy == "fingerprint") {
                        HotUpdaterUpdateStrategy.FINGERPRINT
                    } else {
                        HotUpdaterUpdateStrategy.APP_VERSION
                    }
                val update =
                    hotUpdater.checkForUpdate(HotUpdaterCheckOptions(updateStrategy = strategy))
                        ?: return@withTimeoutOrNull "upToDate"
                when {
                    // A newer Release of the bundle this start runs: nothing to download.
                    update.transitionKind == "ADOPT_RELEASE" -> if (update.updateBundle()) "upToDate" else "failed"

                    // Downloads in the background.
                    !update.shouldForceUpdate -> "pending".also { scope.launch { runCatching { update.updateBundle() } } }

                    update.updateBundle() -> "ready"

                    else -> "failed"
                }
            } catch (error: CancellationException) {
                throw error
            } catch (error: Exception) {
                "failed"
            }
        } ?: "pending"

    /** Runs [callback] on the main thread once React Native has started. */
    fun whenStarted(callback: () -> Unit) {
        if (started) callback() else onStarted.add(callback)
    }

    /**
     * Runs [callback] on the main thread once the JavaScript bundle has loaded,
     * when React Native can take a deep link: before that, its React host drops
     * new intents.
     */
    fun whenBundleLoaded(callback: () -> Unit) {
        if (bundleLoaded) callback() else onBundleLoaded.add(callback)
    }
}

/**
 * A native update check a scenario turns on: the example's ([MAIN_KEY]), or
 * the widget's, which also turns the widget on ([WIDGET_KEY]). The E2E control
 * server writes it to this app's shared preferences; resetting the app
 * removes it.
 */
internal class NativeUpdateCheckRequest(
    val baseURL: String,
    val updateStrategy: String,
    val nonce: String,
    val requestTimeoutMillis: Long,
    val checkTimeoutMillis: Long,
) {
    /** Publishes `<nonce>:<status>` as [field] of the control server's screen state. */
    suspend fun report(
        status: String,
        field: String,
    ) {
        withContext(Dispatchers.IO) {
            runCatching {
                val base = URL(baseURL)
                val connection = URL(base.protocol, base.host, base.port, "/e2e/screen-state").openConnection() as HttpURLConnection
                connection.requestMethod = "POST"
                connection.connectTimeout = 5_000
                connection.readTimeout = 5_000
                connection.doOutput = true
                connection.setRequestProperty("Content-Type", "application/json")
                connection.outputStream.use {
                    it.write(JSONObject().put(field, "$nonce:$status").toString().toByteArray())
                }
                connection.responseCode
                connection.disconnect()
            }
        }
    }

    companion object {
        const val MAIN_KEY = "nativeCheck"
        const val WIDGET_KEY = "widget"

        fun read(
            context: Context,
            key: String,
        ): NativeUpdateCheckRequest? {
            val value =
                context
                    .getSharedPreferences("HotUpdaterE2E", Context.MODE_PRIVATE)
                    .getString(key, null) ?: return null
            return runCatching {
                val json = JSONObject(value)
                NativeUpdateCheckRequest(
                    baseURL = json.getString("baseURL"),
                    updateStrategy = json.getString("updateStrategy"),
                    nonce = json.getString("nonce"),
                    requestTimeoutMillis = json.optLong("requestTimeoutMs", 5_000),
                    checkTimeoutMillis = json.optLong("checkTimeoutMs", 10_000),
                )
            }.getOrNull()
        }
    }
}
